import React, { useState, useEffect, useCallback, useRef } from 'react';
import { SnakeGame, GameState } from './game';
import { Direction } from './snake';
import { FoodItem, FoodType, Position } from './food';

const TILE_SIZE = 20; // Size of each tile in pixels
const GAME_SPEED_FPS = 10; // Frames per second for game logic update
const GAME_REFRESH_RATE = 1000 / GAME_SPEED_FPS;

const BOARD_SIZES = {
  normal: { cols: 22, rows: 22 },
  large: { cols: 30, rows: 30 },
};

const SnakeGamePage: React.FC = () => {
  const [boardConfig, setBoardConfig] = useState(BOARD_SIZES.normal);
  const gameRef = useRef<SnakeGame>(new SnakeGame(boardConfig.cols, boardConfig.rows));
  const [gameState, setGameState] = useState<GameState>(gameRef.current.getGameState());
  const [lastUpdateTime, setLastUpdateTime] = useState<number>(0);
  const [isPlaying, setIsPlaying] = useState<boolean>(false);
  const animationFrameIdRef = useRef<number | null>(null);

  const gameLoop = useCallback((timestamp: number) => {
    if (!isPlaying || gameState.gameOver) {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
        animationFrameIdRef.current = null;
      }
      return;
    }

    // lastUpdateTime is now initialized with performance.now() by start/restart actions.
    const deltaTime = timestamp - lastUpdateTime;
    let currentEngineGameOver = false;

    if (deltaTime >= GAME_REFRESH_RATE) {
      gameRef.current.update();
      const newGameState = gameRef.current.getGameState();
      setGameState(newGameState);
      setLastUpdateTime(timestamp); // Mark time of this successful update

      currentEngineGameOver = newGameState.gameOver;
      if (currentEngineGameOver) {
        setIsPlaying(false);
        return; // Stop the loop for this frame
      }
    }

    // If still playing and not game over from this tick, request next frame
    if (isPlaying && !currentEngineGameOver) { 
        animationFrameIdRef.current = requestAnimationFrame(gameLoop);
    } else if (animationFrameIdRef.current) { // Ensure cleanup if isPlaying was set to false by gameOver
        cancelAnimationFrame(animationFrameIdRef.current);
        animationFrameIdRef.current = null;
    }
  }, [isPlaying, gameState.gameOver, lastUpdateTime, setLastUpdateTime, setIsPlaying, setGameState, GAME_REFRESH_RATE]);

  const handleRestart = useCallback((newBoardConfig = boardConfig) => { // Allow passing new config for size change
    gameRef.current = new SnakeGame(newBoardConfig.cols, newBoardConfig.rows);
    setGameState(gameRef.current.getGameState());
    gameRef.current = new SnakeGame(newBoardConfig.cols, newBoardConfig.rows);
    setGameState(gameRef.current.getGameState());
    setLastUpdateTime(performance.now()); // Initialize for immediate start
    setIsPlaying(true);
  }, [boardConfig, setIsPlaying, setGameState, setLastUpdateTime]);

  const handleSizeChange = useCallback((size: 'normal' | 'large') => {
    const newConfig = BOARD_SIZES[size];
    setBoardConfig(newConfig); // The useEffect for boardConfig will handle the actual restart
  }, [/* setBoardConfig is stable, no need for handleRestart here */]);

  const handleKeyDown = useCallback((e: KeyboardEvent) => {
    let newDirection: Direction | null = null;
    switch (e.key) {
      case 'ArrowUp': case 'w': case 'W': newDirection = Direction.UP; break;
      case 'ArrowDown': case 's': case 'S': newDirection = Direction.DOWN; break;
      case 'ArrowLeft': case 'a': case 'A': newDirection = Direction.LEFT; break;
      case 'ArrowRight': case 'd': case 'D': newDirection = Direction.RIGHT; break;
      case 'r': case 'R': // Restart game
        handleRestart(boardConfig); // Pass current boardConfig
        return;
      default: break;
    }
    if (!isPlaying || gameState.gameOver) {
      if (e.key.toLowerCase() === 'r') { // Allow restart even if not playing or game over
        handleRestart(boardConfig);
      }
      return;
    }

    if (newDirection) {
      e.preventDefault(); // Prevent page scrolling with arrow keys
      gameRef.current.changeDirection(newDirection);
    } else if (e.key.toLowerCase() === 'r') { // Restart during gameplay
      handleRestart(boardConfig);
    }
  }, [isPlaying, gameState.gameOver, handleRestart, boardConfig]);

  // Effect for adding/removing the keydown listener for the primary handleKeyDown
  useEffect(() => {
    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      // animationFrameIdRef.current cancellation is handled by other effects
    };
  }, [handleKeyDown]);

  // Effect to re-initialize gameRef if boardConfig changes
  useEffect(() => {
    gameRef.current = new SnakeGame(boardConfig.cols, boardConfig.rows);
    setGameState(gameRef.current.getGameState());
    setLastUpdateTime(0);
    setIsPlaying(false); // Ensure game is paused when board config changes
    if (animationFrameIdRef.current) {
      cancelAnimationFrame(animationFrameIdRef.current);
      animationFrameIdRef.current = null;
    }
    // The main game loop useEffect will handle starting if isPlaying becomes true.

    // Cleanup function for this effect if boardConfig changes again
    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
      }
    };
  }, [boardConfig]); // Re-run ONLY when boardConfig changes.

  // Main useEffect for controlling the game loop based on isPlaying and gameState.gameOver
  useEffect(() => {
    if (isPlaying && !gameState.gameOver) {
      // lastUpdateTime is set to 0 by the action that starts the game (Start button or Restart)
      // gameLoop will handle the first frame timing using this 0 value.
      animationFrameIdRef.current = requestAnimationFrame(gameLoop);
    } else {
      // This 'else' handles stopping when isPlaying becomes false OR gameState.gameOver becomes true
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
        animationFrameIdRef.current = null;
      }
    }
    // Cleanup: always cancel on unmount or when dependencies change before re-running
    return () => {
      if (animationFrameIdRef.current) {
        cancelAnimationFrame(animationFrameIdRef.current);
        animationFrameIdRef.current = null;
      }
    };
  }, [isPlaying, gameState.gameOver, gameLoop]);

  const { boardWidth, boardHeight, snake, food, score, gameOver, specialFoodTimeRemaining } = gameState;

  const renderTile = (item: Position, type: 'snake' | 'food' | 'special-food', key: string) => {
    let bgColor = 'bg-green-500'; // Default snake color
    if (type === 'food') bgColor = 'bg-red-500';
    if (type === 'special-food') bgColor = 'bg-purple-500 animate-pulse';

    return (
      <div
        key={key}
        className={`absolute ${bgColor}`}
        style={{
          width: TILE_SIZE,
          height: TILE_SIZE,
          left: item.x * TILE_SIZE,
          top: item.y * TILE_SIZE,
          borderRadius: type === 'snake' ? '20%' : '50%', // Square for snake, circle for food
        }}
      />
    );
  };

  return (
    <div className="min-h-screen bg-gray-900 flex flex-col items-center justify-center p-4 font-mono text-white">
      <h1 className="text-4xl font-bold mb-4">Snake Game</h1>
      <div className="mb-2 flex justify-center space-x-2">
        <button 
          onClick={() => handleSizeChange('normal')}
          className={`px-3 py-1 rounded ${boardConfig.cols === BOARD_SIZES.normal.cols ? 'bg-green-500' : 'bg-gray-600 hover:bg-gray-500'} text-white`}
        >
          Normal Board
        </button>
        <button 
          onClick={() => handleSizeChange('large')}
          className={`px-3 py-1 rounded ${boardConfig.cols === BOARD_SIZES.large.cols ? 'bg-green-500' : 'bg-gray-600 hover:bg-gray-500'} text-white`}
        >
          Large Board
        </button>
      </div>
      <div className="mb-4 flex justify-between items-center w-full max-w-md">
        <div className="text-xl">Score: {score}</div>
        {typeof specialFoodTimeRemaining === 'number' && specialFoodTimeRemaining > 0 && (
          <div className="text-xl text-purple-400 animate-pulse">
            Special Food: {specialFoodTimeRemaining}s
          </div>
        )}
        <button 
            onClick={() => handleRestart(boardConfig)} // Pass current boardConfig
            className="px-4 py-2 bg-blue-500 text-white font-bold rounded hover:bg-blue-400 text-lg"
          >
            Restart (R)
        </button>
      </div>

      {gameOver && (
        <div className="absolute inset-0 bg-black bg-opacity-75 flex flex-col items-center justify-center z-10">
          <h2 className="text-5xl text-red-500 font-bold mb-4">GAME OVER</h2>
          <p className="text-2xl mb-4">Final Score: {score}</p>
          <button 
            onClick={() => handleRestart(boardConfig)} // Pass current boardConfig
            className="px-6 py-3 bg-yellow-500 text-black font-bold rounded hover:bg-yellow-400 text-xl"
          >
            Play Again (R)
          </button>
        </div>
      )}

      <div
        className="relative border-4 border-gray-700 bg-gray-800 grid overflow-hidden" // Added overflow-hidden for start button positioning
        style={{
          width: boardWidth * TILE_SIZE,
          height: boardHeight * TILE_SIZE,
          // gridTemplateColumns: `repeat(${boardWidth}, 1fr)`,
          // gridTemplateRows: `repeat(${boardHeight}, 1fr)`,
          // Using absolute positioning for snake/food, so grid lines are for visual bg if needed
        }}
      >
        {/* Render Snake Segments */}
        {snake.map((segment, index) => renderTile(segment, 'snake', `snake-${index}`))}
        
        {/* Render Food Items */}
        {food.map((foodItem, index) => 
          renderTile(foodItem.position, foodItem.type === FoodType.SPECIAL ? 'special-food' : 'food', `food-${index}`)
        )}

        {!isPlaying && !gameState.gameOver && (
          <div className="absolute inset-0 bg-black bg-opacity-60 flex flex-col items-center justify-center z-10">
            <button
              onClick={() => {
                gameRef.current = new SnakeGame(boardConfig.cols, boardConfig.rows);
                setGameState(gameRef.current.getGameState());
                setLastUpdateTime(performance.now()); // Initialize for immediate start
                setIsPlaying(true);
              }}
              className="px-8 py-4 bg-green-600 text-white font-bold rounded-lg hover:bg-green-500 text-3xl shadow-xl transition-transform transform hover:scale-105 focus:outline-none focus:ring-4 focus:ring-green-400 focus:ring-opacity-50"
              style={{ fontFamily: '"Press Start 2P", cursive' }}
            >
              Start Game
            </button>
          </div>
        )}
      </div>
      <div className="mt-4 text-sm text-gray-400">
        Use Arrow Keys or WASD to move. Press 'R' to restart.
      </div>
    </div>
  );
};

export default SnakeGamePage;
