export interface Position {
  x: number;
  y: number;
}

export interface Paddle {
  position: Position;
  width: number;
  height: number;
}

export interface Ball {
  position: Position;
  radius: number;
  velocity: Position; // x and y components of velocity
}

export interface Brick {
  position: Position;
  width: number;
  height: number;
  isAlive: boolean;
  color: string; // Color for rendering
}

export const GAME_WIDTH = 800;
export const GAME_HEIGHT = 600;
export const PADDLE_WIDTH = 100;
export const PADDLE_HEIGHT = 20;
export const BALL_RADIUS = 8;
export const BRICK_ROWS = 5;
export const BRICK_COLUMNS = 10;
export const BRICK_WIDTH = GAME_WIDTH / BRICK_COLUMNS - 4; // -4 for padding
export const BRICK_HEIGHT = 20;
export const BRICK_PADDING = 2;
export const BRICK_OFFSET_TOP = 30;
export const BRICK_OFFSET_LEFT = 30;

export class BreakoutGame {
  public paddle: Paddle;
  public ball: Ball;
  public bricks: Brick[][];
  public score: number;
  public lives: number;
  private gameWidth: number;
  private gameHeight: number;

  constructor(gameWidth: number = GAME_WIDTH, gameHeight: number = GAME_HEIGHT) {
    this.gameWidth = gameWidth;
    this.gameHeight = gameHeight;
    this.score = 0;
    this.lives = 3;
    this.paddle = this.createPaddle();
    this.ball = this.createBall();
    this.bricks = this.createBricks();
  }

  private createPaddle(): Paddle {
    return {
      position: {
        x: (this.gameWidth - PADDLE_WIDTH) / 2,
        y: this.gameHeight - PADDLE_HEIGHT - 10, // 10px from bottom
      },
      width: PADDLE_WIDTH,
      height: PADDLE_HEIGHT,
    };
  }

  private createBall(): Ball {
    return {
      position: {
        x: this.gameWidth / 2,
        y: this.paddle.position.y - BALL_RADIUS - 5, // Start above paddle
      },
      radius: BALL_RADIUS,
      velocity: { x: 4, y: -4 }, // Initial speed and direction
    };
  }

  private createBricks(): Brick[][] {
    const bricks: Brick[][] = [];
    const brickColors = ['#FF0000', '#FFA500', '#FFFF00', '#008000', '#0000FF']; // Red, Orange, Yellow, Green, Blue

    for (let r = 0; r < BRICK_ROWS; r++) {
      bricks[r] = [];
      for (let c = 0; c < BRICK_COLUMNS; c++) {
        const brickX = c * (BRICK_WIDTH + BRICK_PADDING) + BRICK_OFFSET_LEFT;
        const brickY = r * (BRICK_HEIGHT + BRICK_PADDING) + BRICK_OFFSET_TOP;
        bricks[r][c] = {
          position: { x: brickX, y: brickY },
          width: BRICK_WIDTH,
          height: BRICK_HEIGHT,
          isAlive: true,
          color: brickColors[r % brickColors.length],
        };
      }
    }
    return bricks;
  }

  public movePaddle(newX: number): void {
    this.paddle.position.x = Math.max(
      0,
      Math.min(newX, this.gameWidth - this.paddle.width)
    );
  }

  public update(): void {
    if (this.lives <= 0) return; // Game over

    // Move ball
    this.ball.position.x += this.ball.velocity.x;
    this.ball.position.y += this.ball.velocity.y;

    // Ball collision with walls
    // Left or right wall
    if (this.ball.position.x - this.ball.radius < 0 || this.ball.position.x + this.ball.radius > this.gameWidth) {
      this.ball.velocity.x = -this.ball.velocity.x;
      // Adjust position to prevent sticking
      if (this.ball.position.x - this.ball.radius < 0) this.ball.position.x = this.ball.radius;
      if (this.ball.position.x + this.ball.radius > this.gameWidth) this.ball.position.x = this.gameWidth - this.ball.radius;
    }
    // Top wall
    if (this.ball.position.y - this.ball.radius < 0) {
      this.ball.velocity.y = -this.ball.velocity.y;
      this.ball.position.y = this.ball.radius; // Adjust position
    }

    // Ball collision with paddle
    if (
      this.ball.position.y + this.ball.radius > this.paddle.position.y &&
      this.ball.position.y - this.ball.radius < this.paddle.position.y + this.paddle.height &&
      this.ball.position.x + this.ball.radius > this.paddle.position.x &&
      this.ball.position.x - this.ball.radius < this.paddle.position.x + this.paddle.width
    ) {
      this.ball.velocity.y = -this.ball.velocity.y;
      this.ball.position.y = this.paddle.position.y - this.ball.radius; // Place ball on top of paddle
      // Optional: Change ball's x velocity based on where it hits the paddle
      const hitPosition = (this.ball.position.x - (this.paddle.position.x + this.paddle.width / 2)) / (this.paddle.width / 2);
      this.ball.velocity.x = hitPosition * 5; // Max x-velocity change
    }

    // Ball collision with bricks
    for (let r = 0; r < BRICK_ROWS; r++) {
      for (let c = 0; c < BRICK_COLUMNS; c++) {
        const brick = this.bricks[r][c];
        if (brick.isAlive) {
          if (
            this.ball.position.x + this.ball.radius > brick.position.x &&
            this.ball.position.x - this.ball.radius < brick.position.x + brick.width &&
            this.ball.position.y + this.ball.radius > brick.position.y &&
            this.ball.position.y - this.ball.radius < brick.position.y + brick.height
          ) {
            brick.isAlive = false;
            this.score += 10;
            this.ball.velocity.y = -this.ball.velocity.y; // Simple bounce
            // TODO: More precise collision detection (which side was hit)
            break; // Assume one brick hit per frame for simplicity
          }
        }
      }
    }

    // Ball misses paddle (bottom wall)
    if (this.ball.position.y + this.ball.radius > this.gameHeight) {
      this.lives--;
      if (this.lives > 0) {
        this.resetBallAndPaddle();
      } else {
        // Game Over logic here (e.g., stop game, show message)
        console.log('Game Over');
      }
    }

    // Check for win condition
    if (this.bricks.every(row => row.every(brick => !brick.isAlive))) {
        // Win logic here (e.g., next level, show message)
        console.log('You Win!');
        // For now, just reset the game or stop
        this.resetGame();
    }
  }

  public resetBallAndPaddle(): void {
    this.paddle = this.createPaddle();
    this.ball = this.createBall();
  }

  public resetGame(): void {
    this.score = 0;
    this.lives = 3;
    this.bricks = this.createBricks();
    this.resetBallAndPaddle();
  }

  public getGameState() {
    return {
      paddle: this.paddle,
      ball: this.ball,
      bricks: this.bricks,
      score: this.score,
      lives: this.lives,
      gameWidth: this.gameWidth,
      gameHeight: this.gameHeight,
      gameOver: this.lives <= 0,
      gameWon: this.bricks.every(row => row.every(brick => !brick.isAlive))
    };
  }
}
