import { Position } from './food'; // Assuming Position is in food.ts or a shared types file

export enum Direction {
  UP = 'UP',
  DOWN = 'DOWN',
  LEFT = 'LEFT',
  RIGHT = 'RIGHT',
}

export class Snake {
  public body: Position[];
  public direction: Direction;
  private pendingDirection: Direction | null = null;
  private initialPosition: Position;

  constructor(initialPosition: Position = { x: 10, y: 10 }) {
    this.initialPosition = initialPosition;
    this.direction = Direction.RIGHT; // Default starting direction
    // Initialize with length 3, assuming RIGHT direction
    this.body = [
      { ...this.initialPosition }, // Head
      { x: this.initialPosition.x - 1, y: this.initialPosition.y }, // Body segment 1
      { x: this.initialPosition.x - 2, y: this.initialPosition.y }  // Body segment 2 (tail)
    ];
  }

  public move(boardWidth: number, boardHeight: number): void {
    if (this.pendingDirection) {
      // Prevent immediate 180-degree turns
      if (
        (this.pendingDirection === Direction.UP && this.direction !== Direction.DOWN) ||
        (this.pendingDirection === Direction.DOWN && this.direction !== Direction.UP) ||
        (this.pendingDirection === Direction.LEFT && this.direction !== Direction.RIGHT) ||
        (this.pendingDirection === Direction.RIGHT && this.direction !== Direction.LEFT)
      ) {
        this.direction = this.pendingDirection;
      }
      this.pendingDirection = null;
    }

    const head = { ...this.body[0] }; // New head based on current head

    switch (this.direction) {
      case Direction.UP:
        head.y -= 1;
        break;
      case Direction.DOWN:
        head.y += 1;
        break;
      case Direction.LEFT:
        head.x -= 1;
        break;
      case Direction.RIGHT:
        head.x += 1;
        break;
    }

    // Add new head
    this.body.unshift(head);
    // Remove tail to simulate movement
    this.body.pop();
  }

  public grow(): void {
    // Add a new segment to the snake's body, typically at the tail's position before the pop in move().
    // Since move() now always pops, grow() must add a segment to achieve net growth.
    // We add a segment that's a copy of the (new) last segment to extend it.
    if (this.body.length > 0) { // Should always be true if snake exists
      this.body.push({ ...this.body[this.body.length - 1] });
    }
  }

  public changeDirection(newDirection: Direction): void {
    // Store the pending direction. It will be applied at the start of the next move().
    // This prevents multiple direction changes within a single game tick and handles 180-degree turn issues.
    this.pendingDirection = newDirection;
  }

  public checkSelfCollision(potentialHead?: Position): boolean {
    const checkPosition = potentialHead ? potentialHead : this.body[0];
    // Check against all body segments except the last one (tail), as it will move.
    // If the snake has only 1 or 2 segments, self-collision isn't possible in this way.
    for (let i = 0; i < this.body.length - 1; i++) {
      if (this.body[i].x === checkPosition.x && this.body[i].y === checkPosition.y) {
        return true;
      }
    }
    return false;
  }

  public getHeadPosition(): Position {
    return { ...this.body[0] }; // Return a copy
  }

  public getNextHeadPosition(): Position {
    let currentDirection = this.direction;
    // Consider pending direction for the *next* move's calculation
    if (this.pendingDirection) {
      if (
        (this.pendingDirection === Direction.UP && this.direction !== Direction.DOWN) ||
        (this.pendingDirection === Direction.DOWN && this.direction !== Direction.UP) ||
        (this.pendingDirection === Direction.LEFT && this.direction !== Direction.RIGHT) ||
        (this.pendingDirection === Direction.RIGHT && this.direction !== Direction.LEFT)
      ) {
        currentDirection = this.pendingDirection;
      }
    }

    const head = { ...this.body[0] }; // Start with current head position

    switch (currentDirection) {
      case Direction.UP:
        head.y -= 1;
        break;
      case Direction.DOWN:
        head.y += 1;
        break;
      case Direction.LEFT:
        head.x -= 1;
        break;
      case Direction.RIGHT:
        head.x += 1;
        break;
    }
    return head;
  }

  public getBody(): Position[] {
    return this.body.map(p => ({ ...p })); // Return a copy of body segments
  }

  public reset(): void {
    this.direction = Direction.RIGHT;
    this.pendingDirection = null;
    this.body = [
      { ...this.initialPosition },
      { x: this.initialPosition.x - 1, y: this.initialPosition.y },
      { x: this.initialPosition.x - 2, y: this.initialPosition.y }
    ];
  }
}
