export interface Position {
  x: number;
  y: number;
}

export enum FoodType {
  NORMAL = 'NORMAL',
  SPECIAL = 'SPECIAL',
}

export interface FoodItem {
  position: Position;
  type: FoodType;
  points: number;
  createdAt: number; // Timestamp for when the food was created
  expiresAt?: number; // Optional: Timestamp for when special food expires
}

export const SPECIAL_FOOD_DURATION = 5000; // 5 seconds in milliseconds

/**
 * Creates a new food item.
 * @param position The position of the food.
 * @param type The type of food.
 * @param boardWidth The width of the game board.
 * @param boardHeight The height of the game board.
 * @param snakeBody Array of positions occupied by the snake, to avoid placing food on the snake.
 * @param existingFood Array of current food items, to avoid placing food on other food.
 * @returns A new FoodItem or null if no valid position is found (should be rare).
 */
export function createFoodItem(
  boardWidth: number,
  boardHeight: number,
  snakeBody: Position[],
  existingFood: FoodItem[],
  isSpecial: boolean = false
): FoodItem | null {
  let foodPosition: Position | null = null;
  let attempts = 0;
  const maxAttempts = boardWidth * boardHeight; // Avoid infinite loop

  while (!foodPosition && attempts < maxAttempts) {
    let x, y;
    if (boardWidth > 2) {
      x = 1 + Math.floor(Math.random() * (boardWidth - 2)); // Spawn in columns 1 to boardWidth-2
    } else {
      x = Math.floor(Math.random() * boardWidth); // Original behavior for small boards
    }

    if (boardHeight > 2) {
      y = 1 + Math.floor(Math.random() * (boardHeight - 2)); // Spawn in rows 1 to boardHeight-2
    } else {
      y = Math.floor(Math.random() * boardHeight); // Original behavior for small boards
    }
    const potentialPosition = { x, y };

    const isOccupiedBySnake = snakeBody.some(
      (segment) => segment.x === potentialPosition.x && segment.y === potentialPosition.y
    );
    const isOccupiedByFood = existingFood.some(
      (food) => food.position.x === potentialPosition.x && food.position.y === potentialPosition.y
    );

    if (!isOccupiedBySnake && !isOccupiedByFood) {
      foodPosition = potentialPosition;
    }
    attempts++;
  }

  if (!foodPosition) {
    console.warn('Could not find a valid position for new food.');
    return null; // Should ideally not happen if there's space
  }

  const type = isSpecial ? FoodType.SPECIAL : FoodType.NORMAL;
  const points = isSpecial ? 5 : 1;
  const createdAt = Date.now();
  const food: FoodItem = {
    position: foodPosition,
    type,
    points,
    createdAt,
  };

  if (isSpecial) {
    food.expiresAt = createdAt + SPECIAL_FOOD_DURATION;
  }

  return food;
}
